#!/usr/bin/env bash
# Sends exactly 5 synthetic schema-v1 intent messages to intent-events-shadow.
# Uses the EC2 instance role (no static credentials). Does NOT receive or delete.
set -euo pipefail
QUEUE_URL="https://sqs.ap-south-1.amazonaws.com/923233838659/intent-events-shadow"
REGION="ap-south-1"
echo "before: $(aws sqs get-queue-attributes --region "$REGION" --queue-url "$QUEUE_URL" --attribute-names ApproximateNumberOfMessages --query Attributes.ApproximateNumberOfMessages --output text)"
sent=0
aws sqs send-message --region "$REGION" --queue-url "$QUEUE_URL" --message-body '{"schema_version":1,"type":"event","message_key":"sqs-test-20261004-001","brand_id":"sqs_test_brand","event_id":"sqs-test-20261004-001","event_name":"page_viewed","actor_id":"sqs-test-20261004-actor-001","client_id":null,"visitor_id":null,"session_id":"sqs-test-20261004-sess-001","occurred_at":"2026-10-04T06:00:00.000Z","url":"https://sqs-test.invalid/","referrer":null,"user_agent":"sqs-test-agent","session_start":null,"session_end":null,"session_time_spent":null,"raw":null}' --query MessageId --output text && sent=$((sent+1))  # 1 event sqs-test-20261004-001
aws sqs send-message --region "$REGION" --queue-url "$QUEUE_URL" --message-body '{"schema_version":1,"type":"event","message_key":"sqs-test-20261004-002","brand_id":"sqs_test_brand","event_id":"sqs-test-20261004-002","event_name":"product_viewed","actor_id":"sqs-test-20261004-actor-001","client_id":null,"visitor_id":null,"session_id":"sqs-test-20261004-sess-001","occurred_at":"2026-10-04T06:01:00.000Z","url":"https://sqs-test.invalid/products/test-item","referrer":null,"user_agent":"sqs-test-agent","session_start":null,"session_end":null,"session_time_spent":null,"raw":{"product_id":"9000000000001","product_title":"SQS Test Item"}}' --query MessageId --output text && sent=$((sent+1))  # 2 event sqs-test-20261004-002
aws sqs send-message --region "$REGION" --queue-url "$QUEUE_URL" --message-body '{"schema_version":1,"type":"event","message_key":"sqs-test-20261004-003","brand_id":"sqs_test_brand","event_id":"sqs-test-20261004-003","event_name":"product_added_to_cart","actor_id":"sqs-test-20261004-actor-001","client_id":null,"visitor_id":null,"session_id":"sqs-test-20261004-sess-001","occurred_at":"2026-10-04T06:02:00.000Z","url":"https://sqs-test.invalid/products/test-item","referrer":null,"user_agent":"sqs-test-agent","session_start":null,"session_end":null,"session_time_spent":null,"raw":{"product_id":"9000000000001","quantity":1}}' --query MessageId --output text && sent=$((sent+1))  # 3 event sqs-test-20261004-003
aws sqs send-message --region "$REGION" --queue-url "$QUEUE_URL" --message-body '{"schema_version":1,"type":"click","message_key":"sqs-test-20261004-004","brand_id":"sqs_test_brand","event_id":"sqs-test-20261004-004","event_name":"click","actor_id":"sqs-test-20261004-actor-001","client_id":null,"visitor_id":null,"session_id":"sqs-test-20261004-sess-001","occurred_at":"2026-10-04T06:03:00.000Z","url":"https://sqs-test.invalid/products/test-item","referrer":null,"user_agent":"sqs-test-agent","session_start":null,"session_end":null,"session_time_spent":null,"click":{"tag_name":"button","element_id":"sqs-test-atc"},"signals":{},"click_bucket":"useful_click","raw":null}' --query MessageId --output text && sent=$((sent+1))  # 4 click sqs-test-20261004-004
aws sqs send-message --region "$REGION" --queue-url "$QUEUE_URL" --message-body '{"schema_version":1,"type":"session_snapshot","message_key":"session:sqs-test-20261004-sess-001","brand_id":"sqs_test_brand","session_id":"sqs-test-20261004-sess-001","actor_id":"sqs-test-20261004-actor-001","session_start":"2026-10-04T06:00:00.000Z","session_end":"2026-10-04T06:04:00.000Z","session_time_spent":240000,"occurred_at":"2026-10-04T06:04:00.000Z","events_seq":{"1":{"event_name":"page_viewed","event_id":"sqs-test-20261004-001","click_bucket":null,"client_id":null,"visitor_id":null},"2":{"event_name":"product_viewed","event_id":"sqs-test-20261004-002","click_bucket":null,"client_id":null,"visitor_id":null},"3":{"event_name":"product_added_to_cart","event_id":"sqs-test-20261004-003","click_bucket":null,"client_id":null,"visitor_id":null},"4":{"event_name":"click","event_id":"sqs-test-20261004-004","click_bucket":"useful_click","client_id":null,"visitor_id":null}},"source_updated_at":"2026-10-04T06:04:00.000Z"}' --query MessageId --output text && sent=$((sent+1))  # 5 session_snapshot session:sqs-test-20261004-sess-001
echo "sent=$sent (expected 5)"
[ "$sent" -eq 5 ] || { echo "FAILED: sent $sent"; exit 1; }
echo "after: $(aws sqs get-queue-attributes --region "$REGION" --queue-url "$QUEUE_URL" --attribute-names ApproximateNumberOfMessages --query Attributes.ApproximateNumberOfMessages --output text)"
